import java.util.Arrays;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import org.jfree.chart.util.PublicCloneable;
import org.jfree.chart.util.SortOrder;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class DefaultKeyedValues_removeValue_TriageGen0Test {

    private DefaultKeyedValues keyedValues;

    @Before
    public void setUp() {
        keyedValues = new DefaultKeyedValues();
    }

    @Test
    public void testRemoveValue_EmptyList() {
        // Testing behavior on empty list (index 0 should throw IndexOutOfBoundsException based on typical List behavior)
        try {
            keyedValues.removeValue(0);
            fail("Expected IndexOutOfBoundsException");
        } catch (IndexOutOfBoundsException e) {
            // Success
        }
    }

    @Test
    public void testRemoveValue_LastItem() {
        // Adding items to test removal
        keyedValues.addValue("A", 1.0);
        keyedValues.addValue("B", 2.0);
        keyedValues.addValue("C", 3.0);

        int initialCount = keyedValues.getItemCount();
        assertEquals(3, initialCount);

        // Remove the last item (index 2)
        // The condition 'if (index < this.keys.size())' should be false after removal
        // because index 2 is no longer < size 2.
        keyedValues.removeValue(2);

        assertEquals(2, keyedValues.getItemCount());
        assertEquals("A", keyedValues.getKey(0));
        assertEquals("B", keyedValues.getKey(1));
        assertNull("C", keyedValues.getKey(2)); // Depending on implementation, index 2 is gone
    }

    @Test
    public void testRemoveValue_MiddleItemTriggersRebuild() {
        // Adding items to test removal
        keyedValues.addValue("A", 1.0);
        keyedValues.addValue("B", 2.0);
        keyedValues.addValue("C", 3.0);
        keyedValues.addValue("D", 4.0);

        // Remove index 1 ("B")
        // index (1) < keys.size() (3) after removal, so rebuildIndex() should be called
        keyedValues.removeValue(1);

        assertEquals(3, keyedValues.getItemCount());
        assertEquals("A", keyedValues.getKey(0));
        assertEquals("C", keyedValues.getKey(1));
        assertEquals("D", keyedValues.getKey(2));
        assertEquals(2.0, keyedValues.getValue(0).doubleValue(), 0.001);
        assertEquals(3.0, keyedValues.getValue(1).doubleValue(), 0.001);
        assertEquals(4.0, keyedValues.getValue(2).doubleValue(), 0.001);
    }

    @Test
    public void testRemoveValue_FirstItemTriggersRebuild() {
        keyedValues.addValue("A", 1.0);
        keyedValues.addValue("B", 2.0);

        // Remove index 0 ("A")
        // index (0) < keys.size() (1) after removal, so rebuildIndex() should be called
        keyedValues.removeValue(0);

        assertEquals(1, keyedValues.getItemCount());
        assertEquals("B", keyedValues.getKey(0));
        assertEquals(2.0, keyedValues.getValue(0).doubleValue(), 0.001);
    }

    @Test
    public void testRemoveValue_InvalidIndex() {
        keyedValues.addValue("A", 1.0);

        try {
            keyedValues.removeValue(5);
            fail("Expected IndexOutOfBoundsException for out of bounds index");
        } catch (IndexOutOfBoundsException e) {
            // Success
        }
    }
}
